using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;

namespace VisualRelay.Guards;

/// <summary>
/// Pure matcher enforcing that every direct invocation of
/// <c>GitCommitter.CommitAsync(</c> inside <c>tests/VisualRelay.Tests/</c>
/// passes a <c>timeProvider:</c> named argument. Omitting the argument lets
/// the call silently use <see cref="System.TimeProvider.System"/> and burn
/// real wall-clock time in tests — the slip that this guard prevents.
/// <para>Driver-level tests that reach commits through
/// <see cref="VisualRelay.Core.Execution.RelayDriverDependencies.ForTests"/>
/// are out of scope (that seam-wide migration is a separate effort); the guard
/// covers only direct <c>GitCommitter.CommitAsync(</c> calls.</para>
/// <para>Allowlist is empty. The guard is excluded from the <c>check</c> gate
/// and the standalone guards CLI subcommand list.</para>
/// </summary>
public static class TestClockInjectionGuard
{
    /// <summary>Describes a single missing-timeProvider violation (1-based <paramref name="Line"/>).</summary>
    public sealed record Violation(string Path, int Line, string Snippet, string Reason);

    private static readonly string[] SelfExemptFileNames =
        ["TestClockInjectionGuard.cs", "TestClockInjectionGuardTests.cs"];

    private const string TestsDir = "tests/VisualRelay.Tests/";

    private static readonly CSharpParseOptions ParseOptions = new(LanguageVersion.Latest);

    // ── (Path, Source) overload ────────────────────────────────────────────

    /// <summary>
    /// Returns every missing-timeProvider violation across <paramref name="files"/>,
    /// ordered by path (ordinal) then line. Only files whose path starts with
    /// <c>tests/VisualRelay.Tests/</c> are scanned.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(
        IEnumerable<(string Path, string Source)> files)
    {
        var violations = new List<Violation>();

        foreach (var (path, source) in files)
        {
            if (!ShouldScan(path))
                continue;

            var tree = CSharpSyntaxTree.ParseText(source, ParseOptions, path);
            ScanTree(path, tree, violations);
        }

        violations.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return violations;
    }

    // ── (Path, SyntaxTree) overload ────────────────────────────────────────

    /// <summary>
    /// Returns every missing-timeProvider violation across <paramref name="trees"/>,
    /// ordered by path (ordinal) then line. Only trees whose path starts with
    /// <c>tests/VisualRelay.Tests/</c> are scanned. Uses pre-parsed
    /// <see cref="SyntaxTree"/> objects instead of re-parsing string sources.
    /// </summary>
    public static IReadOnlyList<Violation> FindViolations(
        IEnumerable<(string RelativePath, SyntaxTree Tree)> trees)
    {
        var violations = new List<Violation>();

        foreach (var (path, tree) in trees)
        {
            if (!ShouldScan(path))
                continue;

            ScanTree(path, tree, violations);
        }

        violations.Sort((a, b) =>
        {
            var byPath = string.CompareOrdinal(a.Path, b.Path);
            return byPath != 0 ? byPath : a.Line.CompareTo(b.Line);
        });
        return violations;
    }

    // ── Internals ──────────────────────────────────────────────────────────

    private static bool ShouldScan(string path)
    {
        var fileName = Path.GetFileName(path);
        if (SelfExemptFileNames.Contains(fileName))
            return false;

        return path.StartsWith(TestsDir, StringComparison.Ordinal);
    }

    private static void ScanTree(string path, SyntaxTree tree, List<Violation> sink)
    {
        var text = tree.GetText();
        var root = tree.GetRoot();

        foreach (var invocation in root.DescendantNodes().OfType<InvocationExpressionSyntax>())
        {
            if (!IsGitCommitterCommitAsyncCall(invocation))
                continue;

            if (HasTimeProviderArgument(invocation))
                continue;

            var line = LineOf(text, invocation.SpanStart);
            sink.Add(new Violation(path, line, SnippetOf(text, line),
                "GitCommitter.CommitAsync( call missing timeProvider: named argument (inject ManualTimeProvider for tests)"));
        }
    }

    private static bool IsGitCommitterCommitAsyncCall(InvocationExpressionSyntax invocation)
    {
        return invocation.Expression is MemberAccessExpressionSyntax
        {
            Expression: IdentifierNameSyntax { Identifier.Text: "GitCommitter" },
            Name.Identifier.Text: "CommitAsync",
        };
    }

    private static bool HasTimeProviderArgument(InvocationExpressionSyntax invocation)
    {
        if (invocation.ArgumentList is null)
            return true; // No argument list — can't be a real CommitAsync call

        foreach (var arg in invocation.ArgumentList.Arguments)
        {
            if (arg.NameColon?.Name.Identifier.Text == "timeProvider")
                return true;
        }

        return false;
    }

    private static int LineOf(SourceText text, int position) =>
        text.Lines.GetLinePosition(position).Line + 1;

    private static string SnippetOf(SourceText text, int line)
    {
        var s = text.Lines[line - 1].ToString().Trim();
        return s.Length <= 200 ? s : s[..200];
    }
}

using VisualRelay.Guards;

namespace VisualRelay.Tests;

/// <summary>
/// Guard-as-test for <see cref="TestClockInjectionGuard"/>. The guard flags
/// direct <c>GitCommitter.CommitAsync(</c> calls inside
/// <c>tests/VisualRelay.Tests/</c> that omit the <c>timeProvider:</c> named
/// argument — a slip that lets the call silently use real wall-clock time.
/// </summary>
public sealed class TestClockInjectionGuardTests
{
    private readonly CachedSyntaxTreesFixture _trees;

    public TestClockInjectionGuardTests(CachedSyntaxTreesFixture trees)
    {
        _trees = trees;
    }

    // ── Inline-snippet unit tests ──────────────────────────────────────────

    /// <summary>
    /// Teeth: a bare <c>GitCommitter.CommitAsync(...)</c> call with no
    /// <c>timeProvider:</c> in a test file is flagged.
    /// </summary>
    [Fact]
    public void CommitAsync_WithoutTimeProvider_IsFlagged()
    {
        const string source = """
            using VisualRelay.Core.Execution;
            class C {
                async Task M() {
                    await GitCommitter.CommitAsync("root", "t", "h", [], [], [],
                        null, null, null, new StubInvoker(), CancellationToken.None);
                }
            }
            """;

        var violations = TestClockInjectionGuard.FindViolations(
            [("tests/VisualRelay.Tests/Foo.cs", source)]);

        var v = Assert.Single(violations);
        Assert.Contains("missing timeProvider:", v.Reason, StringComparison.Ordinal);
    }

    /// <summary>
    /// A <c>GitCommitter.CommitAsync(...)</c> call WITH <c>timeProvider:</c>
    /// is NOT flagged — the injection seam is satisfied.
    /// </summary>
    [Fact]
    public void CommitAsync_WithTimeProvider_IsNotFlagged()
    {
        const string source = """
            using VisualRelay.Core.Execution;
            class C {
                async Task M() {
                    await GitCommitter.CommitAsync("root", "t", "h", [], [], [],
                        null, null, null, new StubInvoker(), CancellationToken.None,
                        timeProvider: TimeProvider.System);
                }
            }
            """;

        var violations = TestClockInjectionGuard.FindViolations(
            [("tests/VisualRelay.Tests/Foo.cs", source)]);

        Assert.Empty(violations);
    }

    /// <summary>
    /// A bare <c>GitCommitter.CommitAsync(...)</c> call outside
    /// <c>tests/VisualRelay.Tests/</c> (e.g. in <c>src/</c>) is NOT flagged —
    /// the guard only scans the test project.
    /// </summary>
    [Fact]
    public void CommitAsync_OutsideTestProject_IsNotFlagged()
    {
        const string source = """
            using VisualRelay.Core.Execution;
            class C {
                async Task M() {
                    await GitCommitter.CommitAsync("root", "t", "h", [], [], [],
                        null, null, null, new StubInvoker(), CancellationToken.None);
                }
            }
            """;

        var violations = TestClockInjectionGuard.FindViolations(
            [("src/VisualRelay.Core/Execution/Foo.cs", source)]);

        Assert.Empty(violations);
    }

    /// <summary>
    /// Happy path: clean code with no <c>GitCommitter.CommitAsync(</c> calls
    /// produces zero violations.
    /// </summary>
    [Fact]
    public void CleanCode_WithNoCommitAsyncCalls_ReportsZero()
    {
        const string source = """
            using VisualRelay.Core.Execution;
            class C {
                async Task M() {
                    await Task.CompletedTask;
                }
            }
            """;

        var violations = TestClockInjectionGuard.FindViolations(
            [("tests/VisualRelay.Tests/Foo.cs", source)]);

        Assert.Empty(violations);
    }

    // ── Live-tree test ─────────────────────────────────────────────────────

    /// <summary>
    /// The live enforcing gate: every C# file under <c>tests/VisualRelay.Tests/</c>
    /// must pass <c>timeProvider:</c> to every direct <c>GitCommitter.CommitAsync(</c>
    /// call. Any omission flips the guard to a build failure.
    /// </summary>
    [Fact]
    public void LiveTree_HasNoMissingTimeProvider()
    {
        var trees = _trees.AllTrees
            .Where(t => t.RelativePath.StartsWith("tests/", StringComparison.Ordinal))
            .ToList();

        var violations = TestClockInjectionGuard.FindViolations(trees);

        Assert.True(violations.Count == 0,
            "TestClockInjectionGuard found GitCommitter.CommitAsync( calls missing timeProvider: " +
            "in tests/VisualRelay.Tests/ (inject ManualTimeProvider or pass TimeProvider.System):\n" +
            string.Join("\n", violations.Select(v => $"{v.Path}:{v.Line}: {v.Reason} — {v.Snippet}")));
    }
}

using VisualRelay.Core.Execution;
using VisualRelay.GitSim;
using static VisualRelay.Tests.GitCommitterGitSimSetup;

namespace VisualRelay.Tests;

/// <summary>
/// Verifies that <c>git commit</c> exit 1 (hook rejection) is treated as a
/// final per-candidate verdict — no retry backoff — so the candidate loop
/// moves to the next message immediately. Virtual time via
/// <see cref="ManualTimeProvider"/> proves zero delay calls.
/// </summary>
public sealed class GitCommitterCommitExit1FailFastTests
{
    /// <summary>
    /// Two candidates, both hook-rejected (exit 1). The second candidate is
    /// attempted with zero delay calls: virtual time never advances because
    /// exit 1 is a final answer, not a transient failure.
    /// </summary>
    [Fact]
    public async Task CommitAsync_CommitExit1_MovesToNextCandidateWithZeroDelay()
    {
        var (sim, repo) = NewRepo();
        using var _ = repo;
        sim.Seed(repo.Root, "src/app.cs", "content");
        sim.Commit(repo.Root, "chore: seed");
        Write(repo, "src/app.cs", "updated");

        // Hook rejects every commit message.
        sim.PreCommitHook = _ => GitSimHookVerdict.Reject("hook: all commits rejected");

        var candidates = new[] { "feat: first candidate", "fix: second candidate" };
        var time = new ManualTimeProvider();
        var startTime = time.GetUtcNow();

        var result = await GitCommitter.CommitAsync(
            repo.Root, "my-task", "abc123", candidates, ["src/app.cs"], [],
            commitToken: null, preRunUntracked: null, tasksDir: null,
            sim, CancellationToken.None, timeProvider: time);

        // Both candidates rejected → overall failure.
        Assert.False(result.Success);
        Assert.NotNull(result.Error);
        Assert.Contains("commit rejected", result.Error, StringComparison.Ordinal);

        // Zero delay: virtual time never advanced. Exit 1 was treated as a
        // final per-candidate verdict — no retry, no backoff, no timer fired.
        Assert.Equal(startTime, time.GetUtcNow());
    }
}

using VisualRelay.Core.Execution;
using VisualRelay.GitSim;
using static VisualRelay.Tests.GitCommitterGitSimSetup;

namespace VisualRelay.Tests;

/// <summary>
/// Verifies that <c>git commit</c> exit 1 (hook rejection) is treated as a
/// final per-candidate verdict — no retry backoff — so the candidate loop
/// moves to the next message immediately. Virtual time via
/// <see cref="ManualTimeProvider"/> proves zero delay calls.
/// </summary>
public sealed class GitCommitterCommitExit1FailFastTests
{
    /// <summary>
    /// Two candidates, both hook-rejected (exit 1). The second candidate is
    /// attempted with zero delay calls: virtual time never advances because
    /// exit 1 is a final answer, not a transient failure.
    /// </summary>
    [Fact]
    public async Task CommitAsync_CommitExit1_MovesToNextCandidateWithZeroDelay()
    {
        var (sim, repo) = NewRepo();
        using var _ = repo;
        sim.Seed(repo.Root, "src/app.cs", "content");
        sim.Commit(repo.Root, "chore: seed");
        Write(repo, "src/app.cs", "updated");

        // Hook rejects every commit message.
        sim.PreCommitHook = _ => GitSimHookVerdict.Reject("hook: all commits rejected");

        var candidates = new[] { "feat: first candidate", "fix: second candidate" };
        var time = new ManualTimeProvider();

        // Use the advance-pump loop so the test completes even before the fix
        // (exit 1 currently retries, which awaits Task.Delay on virtual time).
        var task = GitCommitter.CommitAsync(
            repo.Root, "my-task", "abc123", candidates, ["src/app.cs"], [],
            commitToken: null, preRunUntracked: null, tasksDir: null,
            sim, CancellationToken.None, timeProvider: time);
        while (!task.IsCompleted)
        {
            time.Advance(TimeSpan.FromMilliseconds(250));
            await Task.Yield();
        }
        var result = await task;

        // Both candidates rejected → overall failure.
        Assert.False(result.Success);
        Assert.NotNull(result.Error);
        Assert.Contains("commit rejected", result.Error, StringComparison.Ordinal);

        // Zero delay: virtual time never advanced. Exit 1 was treated as a
        // final per-candidate verdict — no retry, no backoff, no timer fired.
        Assert.Equal(new DateTimeOffset(0, TimeSpan.Zero), time.GetUtcNow());
    }
}
